with session_summary as (select session_id, max(duration_sec) as max_duration_sec, avg(duration_sec) as avg_duration_sec from web_events group by session_id) select sessions.id, sessions.device, session_summary.max_duration_sec, session_summary.avg_duration_sec from sessions left join session_summary on sessions.id = session_summary.session_id order by id, session_summary.avg_duration_sec
